import { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import api from "../api";

function Chat() {
  const userId = Number(localStorage.getItem("userId"));
  const [searchParams] = useSearchParams();

  const paramUser = Number(searchParams.get("user")); // 👈 FROM PROFILE / FEED

  const [messages, setMessages] = useState([]);
  const [contacts, setContacts] = useState([]);
  const [activeUser, setActiveUser] = useState(null);
  const [text, setText] = useState("");

  /* ================= FETCH CHATS ================= */
  useEffect(() => {
    api.get(`/chat/conversation`).then((res) => {
      setMessages(res.data);

      // build contacts list
      const contactMap = {};
      res.data.forEach((m) => {
        const otherUser =
          m.sender_id === userId ? m.receiver_id : m.sender_id;
        if (otherUser) contactMap[otherUser] = true;
      });

      setContacts(Object.keys(contactMap).map(Number));
    });
  }, [userId]);

  /* ================= AUTO OPEN CHAT (FROM PROFILE) ================= */
  useEffect(() => {
    if (paramUser && paramUser !== userId) {
      setActiveUser(paramUser);

      // ensure contact exists
      setContacts((prev) =>
        prev.includes(paramUser) ? prev : [paramUser, ...prev]
      );
    }
  }, [paramUser, userId]);

  /* ================= SEND MESSAGE ================= */
  const sendMessage = () => {
    if (!text || !activeUser) return;

    api.post("/chat", {
      sender_id: userId,
      receiver_id: activeUser,
      batch_id: null,
      message_text: text,
    }).then(() => {
      setMessages([
        ...messages,
        {
          sender_id: userId,
          receiver_id: activeUser,
          message_text: text,
        },
      ]);
      setText("");
    });
  };

  const activeMessages = messages.filter(
    (m) =>
      (m.sender_id === userId && m.receiver_id === activeUser) ||
      (m.sender_id === activeUser && m.receiver_id === userId)
  );

  return (
    <div className="chat-layout">
      {/* ===== SIDEBAR ===== */}
      <aside className="chat-sidebar glass">
        <h3>Chats</h3>

        {contacts.length === 0 && (
          <p className="empty-text">No conversations yet</p>
        )}

        {contacts.map((id) => (
          <div
            key={id}
            className={`chat-contact ${activeUser === id ? "active" : ""}`}
            onClick={() => setActiveUser(id)}
          >
            <div className="avatar-sm">
              <svg viewBox="0 0 24 24">
                <circle cx="12" cy="8" r="4" />
                <path d="M4 20c0-4 4-6 8-6s8 2 8 6" />
              </svg>
            </div>
            <span>User {id}</span>
          </div>
        ))}
      </aside>

      {/* ===== CHAT WINDOW ===== */}
      <main className="chat-main glass">
        {!activeUser ? (
          <div className="chat-empty">
            <p>Select a conversation</p>
          </div>
        ) : (
          <>
            <div className="chat-header">
              <span>Chat with User {activeUser}</span>
            </div>

            <div className="chat-messages">
              {activeMessages.map((m, i) => (
                <div
                  key={i}
                  className={`chat-bubble ${
                    m.sender_id === userId ? "sent" : "received"
                  }`}
                >
                  {m.message_text}
                </div>
              ))}
            </div>

            <div className="chat-input">
              <input
                placeholder="Type a message..."
                value={text}
                onChange={(e) => setText(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && sendMessage()}
              />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

export default Chat;
